class Solution {
public:
    static long long cross(const vector<int>& O, const vector<int>& A, const vector<int>& B) {
        return 1LL * (A[0] - O[0]) * (B[1] - O[1]) - 1LL * (A[1] - O[1]) * (B[0] - O[0]);
    }

    vector<vector<int>> outerTrees(vector<vector<int>>& trees) {
        int n = (int)trees.size();
        if (n <= 1) return trees;

        sort(trees.begin(), trees.end());

        vector<vector<int>> lower, upper;

        for (auto &p : trees) {
            while (lower.size() >= 2 &&
                   cross(lower[lower.size() - 2], lower[lower.size() - 1], p) < 0) {
                lower.pop_back();
            }
            lower.push_back(p);
        }

        for (int i = n - 1; i >= 0; --i) {
            auto &p = trees[i];
            while (upper.size() >= 2 &&
                   cross(upper[upper.size() - 2], upper[upper.size() - 1], p) < 0) {
                upper.pop_back();
            }
            upper.push_back(p);
        }

        set<pair<int,int>> hull;
        for (auto &p : lower) hull.insert({p[0], p[1]});
        for (auto &p : upper) hull.insert({p[0], p[1]});

        vector<vector<int>> ans;
        for (auto &pt : hull) ans.push_back({pt.first, pt.second});
        return ans;
    }
};

