Point p0;

// Cross product of (p1-p0) and (p2-p0)
long long cross(Point p0, Point p1, Point p2) {
    return (p1.x - p0.x) * (p2.y - p0.y) - (p2.x - p0.x) * (p1.y - p0.y);
}

// Compare function for sorting by polar angle around p0
int compare(const void *a, const void *b) {
    Point *p1 = (Point *)a;
    Point *p2 = (Point *)b;
    long long c = cross(p0, *p1, *p2);
    if (c == 0) {
        // If collinear, keep the closer one first
        long long d1 = (p1->x - p0.x) * (p1->x - p0.x) + (p1->y - p0.y) * (p1->y - p0.y);
        long long d2 = (p2->x - p0.x) * (p2->x - p0.x) + (p2->y - p0.y) * (p2->y - p0.y);
        return (d1 < d2) ? -1 : 1;
    }
    return (c > 0) ? -1 : 1;
}

int main() {
    int n;
    scanf("%d", &n);

    Point *points = (Point *)malloc(n * sizeof(Point));
    for (int i = 0; i < n; i++) {
        scanf("%lld %lld", &points[i].x, &points[i].y);
    }

    // Find the bottom-most point (and leftmost if tie)
    int minIdx = 0;
    for (int i = 1; i < n; i++) {
        if (points[i].y < points[minIdx].y || 
            (points[i].y == points[minIdx].y && points[i].x < points[minIdx].x)) {
            minIdx = i;
        }
    }

    // Swap the chosen point to index 0
    Point temp = points[0];
    points[0] = points[minIdx];
    points[minIdx] = temp;

    p0 = points[0];
    qsort(points + 1, n - 1, sizeof(Point), compare);

    // Build convex hull using Graham Scan
    Point *stack = (Point *)malloc(n * sizeof(Point));
    int top = 0;

    stack[top++] = points[0];

    // Add first point after p0
    int k;
    for (k = 1; k < n; k++) {
        if (k == n - 1 || cross(p0, points[k], points[n - 1]) != 0) {
            break;
        }
    }
    stack[top++] = points[k];

    for (int i = k + 1; i < n; i++) {
        while (top >= 2 && cross(stack[top - 2], stack[top - 1], points[i]) <= 0) {
            top--;
        }
        stack[top++] = points[i];
    }

    // Output convex hull points
    for (int i = 0; i < top; i++) {
        printf("%lld %lld\n", stack[i].x, stack[i].y);
    }

    free(points);
    free(stack);

    return 0;
}

