int cmp(const void *a, const void *b) {
    Point *p = (Point*)a, *q = (Point*)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

ll cross(Point O, Point A, Point B) {
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

int on_segment(Point A, Point B, Point P) {
    // Check if P is on segment AB (assuming collinear)
    return (P.x >= (A.x < B.x ? A.x : B.x)) && (P.x <= (A.x > B.x ? A.x : B.x)) &&
           (P.y >= (A.y < B.y ? A.y : B.y)) && (P.y <= (A.y > B.y ? A.y : B.y));
}

int main() {
    int n;
    scanf("%d", &n);
    Point pts[100005];
    for (int i = 0; i < n; i++) scanf("%lld %lld", &pts[i].x, &pts[i].y);

    qsort(pts, n, sizeof(Point), cmp);

    // Andrew's monotone chain
    Point hull[200010];
    int k = 0;

    for (int i = 0; i < n; i++) {
        while (k >= 2 && cross(hull[k-2], hull[k-1], pts[i]) < 0) k--;
        hull[k++] = pts[i];
    }
    for (int i = n-2, t = k+1; i >= 0; i--) {
        while (k >= t && cross(hull[k-2], hull[k-1], pts[i]) < 0) k--;
        hull[k++] = pts[i];
    }
    k--; // remove last point (same as first)

    // Now find all points on the boundary
    int on_hull[100005] = {0};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < k; j++) {
            Point A = hull[j], B = hull[(j+1)%k];
            if (cross(A, B, pts[i]) == 0 && on_segment(A, B, pts[i])) {
                on_hull[i] = 1;
                break;
            }
        }
    }

    int cnt = 0;
    for (int i = 0; i < n; i++) if (on_hull[i]) cnt++;
