    if (m == 1) {
        printf("1\n%lld %lld\n", a[0].x, a[0].y);
        free(a);
        return 0;
    }

    // Monotone chain including all boundary points:
    // use strict right turn (< 0) to pop, keeping collinear points.
    Point *h = (Point *)malloc((size_t)(2 * m + 5) * sizeof(Point));
    int k = 0;

    // Lower hull
    for (int i = 0; i < m; i++) {
        while (k >= 2 && cross(h[k - 2], h[k - 1], a[i]) < 0) k--;
        h[k++] = a[i];
    }

    // Upper hull
    int t = k + 1;
    for (int i = m - 2; i >= 0; i--) {
        while (k >= t && cross(h[k - 2], h[k - 1], a[i]) < 0) k--;
        h[k++] = a[i];
    }

    if (k > 1) k--; // last point equals first

    // Remove duplicates from hull list while preserving order
    int *used = (int *)calloc((size_t)k, sizeof(int));
    Point *res = (Point *)malloc((size_t)k * sizeof(Point));
