public class ConvexHull {
    static class Point implements Comparable<Point> {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
        public int compareTo(Point other) {
            if (this.x != other.x) return Long.compare(this.x, other.x);
            return Long.compare(this.y, other.y);
        }
    }

    // Cross product of vectors (a->b) and (a->c)
    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    public static List<Point> convexHull(Point[] points) {
        int n = points.length;
        if (n <= 1) return Arrays.asList(points);
        Arrays.sort(points);

        List<Point> hull = new ArrayList<>();

        // Build lower hull
        for (int i = 0; i < n; i++) {
            while (hull.size() >= 2 && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), points[i]) < 0)
                hull.remove(hull.size()-1);
            hull.add(points[i]);
        }

        // Build upper hull
        int lowerSize = hull.size();
        for (int i = n-2; i >= 0; i--) {
            while (hull.size() > lowerSize && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), points[i]) < 0)
                hull.remove(hull.size()-1);
            hull.add(points[i]);
        }

        // Remove last point because it's the same as first
        hull.remove(hull.size()-1);
        return hull;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());
            points[i] = new Point(x, y);
        }

