import sys

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull_all_boundary(points):
    pts = sorted(set(points))
    n = len(pts)
    if n <= 1:
        return pts

    # Check if all points are collinear
    all_collinear = True
    for i in range(2, n):
        if cross(pts[0], pts[1], pts[i]) != 0:
            all_collinear = False
            break
    if all_collinear:
        return pts

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) < 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) < 0:
            upper.pop()
        upper.append(p)

    hull = lower[:-1] + upper[:-1]

    # Remove duplicates while preserving order
    seen = set()
    res = []
    for p in hull:
        if p not in seen:
            seen.add(p)
            res.append(p)
    return res

